"use client";
import * as React from "react";
import type { VariantProps } from "class-variance-authority";
import { ToggleGroup as ToggleGroupPrimitive } from "./primitive-toggle-group";
import { toggleVariants } from "./toggle";
import { cn } from "./utils";
type Variants = VariantProps<typeof toggleVariants>;
const ToggleGroupContext = React.createContext<Variants>({});
function ToggleGroup({
  className,
  variant,
  size,
  spacing = 0,
  orientation,
  style,
  children,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Root> &
  Variants & { spacing?: number }) {
  return (
    <ToggleGroupPrimitive.Root
      data-slot="toggle-group"
      data-spacing={spacing}
      data-orientation={orientation ?? "horizontal"}
      orientation={orientation}
      className={cn("roc-ui", className)}
      style={
        {
          "--roc-toggle-gap": `${spacing * 4}px`,
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive.Root>
  );
}
function ToggleGroupItem({
  className,
  variant,
  size,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Item> & Variants) {
  const context = React.useContext(ToggleGroupContext);
  return (
    <ToggleGroupPrimitive.Item
      data-slot="toggle-group-item"
      className={cn(
        toggleVariants({
          variant: variant ?? context.variant,
          size: size ?? context.size,
        }),
        className,
      )}
      {...props}
    />
  );
}
export { ToggleGroup, ToggleGroupItem };

import "./toggle-group.css";

"use client";
// ROC primitive: a set of toggles that behave as one choice (single) or many (multiple).
import * as React from "react";
import { useDirectionContext } from "./primitive-direction-context";
import { Toggle } from "./primitive-toggle";
import { composeEventHandlers, useComposedRefs } from "./primitive-utils";
import {
  ROVING_ROOT,
  handleRovingKey,
  useRovingTabStop,
  type Orientation,
} from "./primitive-roving";

type Context = {
  type: "single" | "multiple";
  values: string[];
  disabled: boolean;
  orientation?: Orientation;
  activate: (value: string) => void;
  deactivate: (value: string) => void;
  fallback: string | null;
};
const GroupContext = React.createContext<Context | null>(null);
const useGroup = () => {
  const context = React.useContext(GroupContext);
  if (!context) throw new Error("ToggleGroup parts must be inside ToggleGroup.Root");
  return context;
};

type Shared = Omit<React.ComponentProps<"div">, "defaultValue" | "dir"> & {
  disabled?: boolean;
  orientation?: Orientation;
  dir?: "ltr" | "rtl";
  loop?: boolean;
  /** Arrow keys move focus between items. Defaults to true. */
  rovingFocus?: boolean;
};
type SingleProps = Shared & {
  type: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
};
type MultipleProps = Shared & {
  type: "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
};

const toArray = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value : value ? [value] : [];

function Root(props: SingleProps | MultipleProps) {
  const {
    type,
    value,
    defaultValue,
    onValueChange,
    disabled = false,
    orientation,
    dir: dirProp,
    loop = true,
    rovingFocus = true,
    onKeyDown,
    ref,
    ...rest
  } = props as Shared & {
    type: "single" | "multiple";
    value?: string | string[];
    defaultValue?: string | string[];
    onValueChange?: (value: any) => void;
  };
  const dir = useDirectionContext(dirProp);
  const [internal, setInternal] = React.useState(() => toArray(defaultValue));
  const values = value === undefined ? internal : toArray(value);
  const change = (next: string[]) => {
    if (value === undefined) setInternal(next);
    onValueChange?.(type === "multiple" ? next : (next[0] ?? ""));
  };
  const roving = useRovingTabStop(
    '[aria-pressed="true"], [role="radio"][aria-checked="true"]',
  );
  const composed = useComposedRefs<HTMLDivElement>(ref, roving.ref);
  return (
    <GroupContext.Provider
      value={{
        type,
        values,
        disabled,
        orientation,
        fallback: roving.fallback,
        activate: (item) => change(type === "multiple" ? [...values, item] : [item]),
        deactivate: (item) => change(values.filter((existing) => existing !== item)),
      }}
    >
      <div
        role={!rovingFocus ? "group" : type === "single" ? "radiogroup" : "toolbar"}
        dir={dir}
        data-orientation={orientation}
        {...{ [ROVING_ROOT]: "" }}
        {...rest}
        ref={composed}
        onKeyDown={composeEventHandlers(onKeyDown, (event) => {
          if (rovingFocus)
            handleRovingKey(event, roving.ref.current, { orientation, dir, loop });
        })}
      />
    </GroupContext.Provider>
  );
}

type ItemProps = Omit<React.ComponentProps<typeof Toggle.Root>, "pressed" | "defaultPressed" | "value"> & {
  value: string;
};

function Item({ value, disabled, ...props }: ItemProps) {
  const group = useGroup();
  const pressed = group.values.includes(value);
  const single = group.type === "single";
  return (
    <Toggle.Root
      data-orientation={group.orientation}
      data-roving-item=""
      data-roving-value={value}
      tabIndex={pressed || group.fallback === value ? 0 : -1}
      {...(single ? { role: "radio", "aria-checked": pressed, "aria-pressed": undefined } : {})}
      {...props}
      disabled={group.disabled || disabled}
      pressed={pressed}
      onPressedChange={(next) =>
        next ? group.activate(value) : group.deactivate(value)
      }
    />
  );
}

export const ToggleGroup = { Root, Item };

"use client";
// ROC primitive: the reading direction set by a DirectionProvider, with no dependencies.
import * as React from "react";

export type Dir = "ltr" | "rtl";

export const DirectionContext = React.createContext<Dir | undefined>(undefined);

/** A `dir` prop wins, then the provider; undefined means "use the CSS direction". */
export function useDirectionContext(local?: Dir): Dir | undefined {
  return local ?? React.useContext(DirectionContext);
}

"use client";
// ROC primitive: a two-state button.
import * as React from "react";
import { Slot } from "./primitive-slot";
import { composeEventHandlers } from "./primitive-utils";
import { useControllableState } from "./use-controllable-state";

type RootProps = Omit<React.ComponentProps<"button">, "defaultValue"> & {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  asChild?: boolean;
};

function Root({
  pressed: pressedProp,
  defaultPressed = false,
  onPressedChange,
  asChild,
  disabled,
  onClick,
  ...props
}: RootProps) {
  const [pressed, setPressed] = useControllableState(
    pressedProp,
    defaultPressed,
    onPressedChange,
  );
  const Comp: React.ElementType = asChild ? Slot.Root : "button";
  return (
    <Comp
      type="button"
      aria-pressed={pressed}
      data-state={pressed ? "on" : "off"}
      data-disabled={disabled ? "" : undefined}
      disabled={disabled}
      {...props}
      onClick={composeEventHandlers(onClick, () => {
        if (!disabled) setPressed(!pressed);
      })}
    />
  );
}

export const Toggle = { Root };

"use client";
// ROC primitive: render the caller's single child with our props merged in (`asChild`).
import * as React from "react";
import { composeRefs } from "./primitive-utils";

type AnyProps = Record<string, any>;

function mergeProps(slotProps: AnyProps, childProps: AnyProps) {
  const merged: AnyProps = { ...childProps };
  for (const key in childProps) {
    const slotValue = slotProps[key];
    const childValue = childProps[key];
    if (/^on[A-Z]/.test(key)) {
      if (slotValue && childValue) {
        merged[key] = (...args: unknown[]) => {
          const result = childValue(...args);
          slotValue(...args);
          return result;
        };
      } else if (slotValue) merged[key] = slotValue;
    } else if (key === "style") {
      merged[key] = { ...slotValue, ...childValue };
    } else if (key === "className") {
      merged[key] = [slotValue, childValue].filter(Boolean).join(" ");
    }
  }
  return { ...slotProps, ...merged };
}

type SlotProps = React.HTMLAttributes<HTMLElement> & {
  children?: React.ReactNode;
  ref?: React.Ref<any>;
};

function Root({ children, ref, ...slotProps }: SlotProps) {
  if (!React.isValidElement(children)) {
    if (React.Children.count(children) > 1) throw new Error("Slot needs one child");
    return null;
  }
  const child = children as React.ReactElement<AnyProps>;
  return React.cloneElement(child, {
    ...mergeProps(slotProps, child.props),
    ref: ref ? composeRefs(ref, child.props.ref) : child.props.ref,
  });
}

export const Slot = { Root };

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

"use client";
// ROC primitive: arrow-key focus movement and a single tab stop for a group of items.
// Items mark themselves with `data-roving-item`; each group marks its root `data-roving-root`.
import * as React from "react";

export type Orientation = "horizontal" | "vertical";
export const ROVING_ROOT = "data-roving-root";
export const ROVING_ITEM = "[data-roving-item]";

const INTENT: Record<string, "prev" | "next" | "first" | "last"> = {
  ArrowLeft: "prev",
  ArrowUp: "prev",
  ArrowRight: "next",
  ArrowDown: "next",
  PageUp: "first",
  Home: "first",
  PageDown: "last",
  End: "last",
};

/** Items that belong to this group (not to a nested one) and can take focus. */
export function focusableItems(root: HTMLElement) {
  return Array.from(root.querySelectorAll<HTMLElement>(ROVING_ITEM)).filter(
    (item) =>
      item.closest(`[${ROVING_ROOT}]`) === root &&
      !item.matches(":disabled, [data-disabled]"),
  );
}

/** Move focus for an arrow/Home/End key. Returns whether the key was handled. */
export function handleRovingKey(
  event: React.KeyboardEvent,
  root: HTMLElement | null,
  options: { orientation?: Orientation; dir?: "ltr" | "rtl"; loop?: boolean },
) {
  if (!root || event.metaKey || event.ctrlKey || event.altKey || event.shiftKey)
    return false;
  const current = (event.target as HTMLElement).closest<HTMLElement>(ROVING_ITEM);
  if (!current || current.closest(`[${ROVING_ROOT}]`) !== root) return false;
  const rtl = (options.dir ?? getComputedStyle(root).direction) === "rtl";
  let key = event.key;
  if (rtl && key === "ArrowLeft") key = "ArrowRight";
  else if (rtl && key === "ArrowRight") key = "ArrowLeft";
  const { orientation, loop = true } = options;
  if (orientation === "vertical" && (key === "ArrowLeft" || key === "ArrowRight"))
    return false;
  if (orientation === "horizontal" && (key === "ArrowUp" || key === "ArrowDown"))
    return false;
  const intent = INTENT[key];
  if (!intent) return false;
  event.preventDefault();
  const items = focusableItems(root);
  const index = items.indexOf(current);
  let target: HTMLElement | undefined;
  if (intent === "first") target = items[0];
  else if (intent === "last") target = items[items.length - 1];
  else {
    const step = intent === "next" ? 1 : -1;
    const next = index + step;
    target = loop
      ? items[(next + items.length) % items.length]
      : items[next];
  }
  if (target && target !== current) target.focus();
  return true;
}

/**
 * One tab stop per group: the selected item, or the first enabled item when none
 * is selected. Items read `fallback` and compare it to their `data-roving-value`.
 */
export function useRovingTabStop(selectedSelector: string) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  const [fallback, setFallback] = React.useState<string | null>(null);
  React.useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    const items = focusableItems(root);
    const next = items.some((item) => item.matches(selectedSelector))
      ? null
      : (items[0]?.dataset.rovingValue ?? null);
    setFallback((previous) => (previous === next ? previous : next));
  });
  return { ref, fallback };
}

